def sum_prime_divisors(n):
    sum = 0
    for p in range(2, int(n ** 0.5) + 1):
        if n % p == 0:
            sum += p
            while n % p == 0:
                n //= p
               sum += p
    return sum

def sort_by_length_and_value(lst):
    """
    Sort a list of lists by length and value.
    """
    def sort_by_length(lst):
        """
        Sort a list of lists by length.
        """
        return sorted(lst, key=lambda x: len(x))

    def sort_by_value(lst):
        """
        Sort a list of lists by value.
        """
        return sorted(lst, key=lambda x: x[0])

    return sort_by_length(sort_by_value(lst))

def inversions(tuples):
    """
    Returns a list of tuples of the form (a, b) where a and b are elements of tuples
    and a > b.
    """
    inversions = []
    for t in tuples:
        for i in range(len(t) - 1):
            if t[i] > t[i + 1]:
                inversions.append((t[i], t[i + 1]))
    return inversions

def assign_pairs(tuple_data):
    result = []
    for t in tuple_data:
        pair = (t[0], t[1])
        if pair in result:
            index = result.index(pair)
            t[2] = index
        else:
            result.append(pair)
            t[2] = len(result) - 1
    return tuple_data

