def pair_elements(tuples):
    """
    Given a list of tuples, assign to each element its pair element from other similar pairs.
    """
    pairs = {}
    for tup in tuples:
        key = tup[0]
        if key in pairs:
            pairs[key] = tup[1]
        else:
            pairs[key] = None
    for tup in tuples:
        if tup[1] in pairs:
            tup[1] = pairs[tup[1]]
    return tuples

def median(a, b, c):
    if a > b and a > c:
        return a
    elif b > a and b > c:
        return b
    elif c > a and c > b:
        return c
    else:
        return (a + b + c) / 3

def find_inversions(tuples):
    """
    Returns a list of tuples, where each tuple contains two elements that are inversions of each other.
    """
    inversions = []
    for i in range(len(tuples)):
        for j in range(i+1, len(tuples)):
            if tuples[i][0] > tuples[j][0] and tuples[i][1] < tuples[j][1]:
                inversions.append((tuples[i], tuples[j]))
    return inversions

