from collections import defaultdict

def check_similar_records(tuples):
    # Create a dictionary to store the counts of each record
    count_dict = defaultdict(int)
    for tuple in tuples:
        # Increment the count for the current record
        count_dict[tuple] += 1

    # Iterate over thecount_dict and find records with similar counts
    similar_records = {}
    for record, count in count_dict.items():
        if count > 0.5 * len(tuples):
            similar_records[record] = count

    return similar_records

